<script>
  var links = [];

  function nameFromUrl(raw) {
    // Derive a friendly name from the URL's last meaningful path segment.
    try {
      var u = new URL(raw);
      var seg = u.pathname.split('/').filter(Boolean).pop();
      if (seg) {
        seg = decodeURIComponent(seg).replace(/[-_]+/g, ' ').replace(/\.[a-z0-9]+$/i, '');
        if (seg.trim()) return seg.trim().replace(/\b\w/g, function(c){ return c.toUpperCase(); });
      }
      return u.hostname.replace(/^www\./, '');
    } catch (e) {
      return raw;
    }
  }

  function normalise(raw) {
    var v = raw.trim();
    if (!v) return null;
    if (!/^https?:\/\//i.test(v)) v = 'https://' + v;
    try { new URL(v); } catch (e) { return null; }
    return v;
  }

  function render() {
    var list = document.getElementById('list');
    var empty = document.getElementById('empty');
    document.getElementById('count').textContent = links.length;
    list.innerHTML = '';
    if (links.length === 0) { empty.style.display = 'block'; return; }
    empty.style.display = 'none';
    links.forEach(function (item) {
      var host = '';
      try { host = new URL(item.url).hostname.replace(/^www\./, ''); } catch (e) {}
      var li = document.createElement('li');
      li.className = 'card';
      li.innerHTML =
        '<div class="title"></div>' +
        '<a href="' + item.url + '" target="_blank" rel="noopener"></a>' +
        '<div class="meta">' + host + ' · saved just now</div>';
      li.querySelector('.title').textContent = item.title;
      li.querySelector('a').textContent = item.url;
      list.appendChild(li);
    });
  }

  function save() {
    var input = document.getElementById('url');
    var err = document.getElementById('err');
    var url = normalise(input.value);
    if (!url) {
      err.textContent = 'That doesn\'t look like a valid link. Try something like example.com/page.';
      err.style.display = 'block';
      return;
    }
    err.style.display = 'none';
    links.unshift({ url: url, title: nameFromUrl(url) });
    input.value = '';
    input.focus();
    render();
  }

  document.getElementById('saveBtn').addEventListener('click', save);
  document.getElementById('url').addEventListener('keydown', function (e) {
    if (e.key === 'Enter') save();
  });

  render();
